import Component from 'flarum/common/Component';
import MessageStream from './MessageStream';
import username from 'flarum/common/helpers/username';
import MessageStreamState from '../states/MessageStreamState';
import Avatar from 'flarum/common/components/Avatar';
import GroupBadge from 'flarum/common/components/GroupBadge';
import Link from 'flarum/common/components/Link';
import app from 'flarum/forum/app';
import ItemList from 'flarum/common/utils/ItemList';
import Button from 'flarum/common/components/Button';
import Dropdown from 'flarum/common/components/Dropdown';
import DetailsModal from './DetailsModal';
import RenameDialogModal from './RenameDialogModal';
import listItems from 'flarum/common/helpers/listItems';
import classList from 'flarum/common/utils/classList';
import extractText from 'flarum/common/utils/extractText';
import leaveDialog from '../utils/leaveDialog';
export default class DialogSection extends Component {
  loading = false;
  /**
   * The permalinked message, taken from the route once. The stream drops it
   * from the address after opening on it, and the route's own copy would
   * still say it afterwards.
   */
  near = null;
  oninit(vnode) {
    super.oninit(vnode);
    this.near = parseInt(m.route.param('near')) || null;
    this.messages = new MessageStreamState(this.requestParams());
    this.messages.refresh();
  }
  requestParams() {
    const params = {
      filter: {
        dialog: this.attrs.dialog.id()
      },
      sort: '-number'
    };
    if (this.near) {
      params.page = {
        near: this.near
      };
    }
    return params;
  }
  view() {
    return m("div", {
      className: classList('DialogSection', {
        'DialogSection--group': this.attrs.dialog.isGroup()
      })
    }, m("div", {
      className: "DialogSection-header"
    }, this.headerAvatar(), m("div", {
      className: "DialogSection-header-info"
    }, this.headerInfo()), m("div", {
      className: "DialogSection-header-actions"
    }, this.actionItems().toArray())), m(MessageStream, {
      dialog: this.attrs.dialog,
      state: this.messages,
      near: this.near
    }));
  }

  /** How many of a group's groups and members the header shows before counting the rest. */
  static HEADER_AVATARS = 3;

  /**
   * The other member's avatar; in a group, the groups it is addressed to and
   * then the other members, as overlapping tiles of one size, the first few
   * shown and the rest counted.
   */
  headerAvatar() {
    const dialog = this.attrs.dialog;
    if (dialog.isGroup()) {
      const groups = (dialog.groups() || []).filter(group => !!group);
      const users = dialog.recipients();
      const shown = DialogSection.HEADER_AVATARS;
      const hidden = groups.length + users.length - shown;
      return m("div", {
        className: "DialogSection-header-avatars"
      }, groups.slice(0, shown).map(group => m(GroupBadge, {
        group: group,
        label: group.namePlural(),
        className: "DialogSection-header-group"
      })), users.slice(0, Math.max(shown - groups.length, 0)).map(user => m(Avatar, {
        user: user
      })), hidden > 0 && m("span", {
        className: "DialogSection-header-more"
      }, "+", hidden));
    }
    return m(Avatar, {
      user: dialog.recipient()
    });
  }

  /**
   * Who the conversation is with: the other member, with their badges, or a
   * group's title and how many are in it, which opens the list of them.
   */
  headerInfo() {
    const dialog = this.attrs.dialog;
    if (dialog.isGroup()) {
      return [m("h2", {
        className: "DialogSection-header-info-title"
      }, dialog.title()), m(Button, {
        className: "Button Button--link DialogSection-members",
        onclick: () => app.modal.show(DetailsModal, {
          dialog
        })
      }, (dialog.groups() || []).length ? app.translator.trans('flarum-messages.forum.dialog_section.details_modal.recipients') : app.translator.trans('flarum-messages.forum.dialog_section.members_button', {
        count: (dialog.users() || []).length
      }))];
    }
    const recipient = dialog.recipient();
    return [m("h2", {
      className: "DialogSection-header-info-title"
    }, recipient && m(Link, {
      href: app.route.user(recipient)
    }, username(recipient)) || username(recipient), !this.recipientCannotReply() ? null : m("span", {
      className: "DialogSection-header-info-helperText"
    }, app.translator.trans('flarum-messages.forum.dialog_section.cannot_reply_text'))), m("div", {
      className: "badges"
    }, listItems(recipient?.badges().toArray() || []))];
  }

  /**
   * Whether to say the other member can't reply: they can't send messages, and
   * the viewer can't send here either. Not to viewers who can't send at all,
   * who aren't told whether anyone else can. Never in a group, where the
   * others still can.
   */
  recipientCannotReply() {
    if (this.attrs.dialog.isGroup()) return false;
    const recipient = this.attrs.dialog.recipient();
    return !recipient || app.session.user.canSendAnyMessage() && !recipient.canSendAnyMessage() && !this.attrs.dialog.canSendMessage();
  }
  actionItems() {
    const items = new ItemList();
    items.add('back', m(Button, {
      className: "Button Button--icon DialogSection-back",
      icon: "fas fa-arrow-left",
      onclick: this.attrs.onback
    }, app.translator.trans('flarum-messages.forum.dialog_section.back_label')));
    items.add('details', m(Dropdown, {
      icon: "fas fa-ellipsis-h",
      className: "DialogSection-controls",
      buttonClassName: "Button Button--icon",
      accessibleToggleLabel: app.translator.trans('flarum-messages.forum.dialog_section.controls_toggle_label'),
      label: app.translator.trans('flarum-messages.forum.dialog_section.controls_toggle_label')
    }, this.controlItems().toArray()));
    return items;
  }
  controlItems() {
    const items = new ItemList();
    items.add('details', m(Button, {
      icon: "fas fa-info-circle",
      onclick: () => app.modal.show(DetailsModal, {
        dialog: this.attrs.dialog
      })
    }, app.translator.trans('flarum-messages.forum.dialog_section.controls.details_button')));

    // Where the forum lets members name groups, and this one may.
    if (this.attrs.dialog.canRename()) {
      items.add('rename', m(Button, {
        icon: "fas fa-pencil-alt",
        onclick: () => app.modal.show(RenameDialogModal, {
          dialog: this.attrs.dialog,
          // The group is told who named it: bring that notice in.
          onsave: () => this.messages.catchUp().then(() => m.redraw())
        })
      }, app.translator.trans('flarum-messages.forum.dialog_section.controls.rename_button')), 50);
    }

    // Only a group: leaving a direct conversation would leave nobody in it.
    if (this.attrs.dialog.isGroup()) {
      items.add('leave', m(Button, {
        icon: "fas fa-sign-out-alt",
        onclick: () => this.leave()
      }, app.translator.trans('flarum-messages.forum.dialog_section.controls.leave_button')), -100);
    }
    return items;
  }

  /** Leaves the group, once the member has confirmed, and closes it. */
  leave() {
    if (!confirm(extractText(app.translator.trans('flarum-messages.forum.dialog_section.leave_confirmation')))) {
      return Promise.resolve();
    }

    // A refusal is shown by the request itself.
    return leaveDialog(this.attrs.dialog).then(() => this.attrs.onback ? this.attrs.onback() : m.route.set(app.route('messages')), () => {});
  }
}
flarum.reg.add('flarum-messages', 'forum/components/DialogSection', DialogSection);