import app from 'flarum/forum/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import Form from 'flarum/common/components/Form';
import Stream from 'flarum/common/utils/Stream';
/** The server's limit, so the field stops where it would be refused. */
const MAX_LENGTH = 50;

/**
 * Names a group, or takes its name away so its members title it again.
 */
export default class RenameDialogModal extends FormModal {
  oninit(vnode) {
    super.oninit(vnode);
    this.name = Stream(this.attrs.dialog.name() || '');
  }
  className() {
    return 'RenameDialogModal Modal--small';
  }
  title() {
    return app.translator.trans('flarum-messages.forum.rename_dialog_modal.title');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m(Form, {
      className: "Form--centered"
    }, m("div", {
      className: "Form-group"
    }, m("label", {
      className: "sr-only",
      for: "RenameDialogModal-name"
    }, app.translator.trans('flarum-messages.forum.rename_dialog_modal.name_label')), m("input", {
      id: "RenameDialogModal-name",
      className: "FormControl",
      bidi: this.name,
      type: "text",
      maxlength: MAX_LENGTH
    }), m("div", {
      className: "helpText"
    }, app.translator.trans('flarum-messages.forum.rename_dialog_modal.help_text'))), m("div", {
      className: "Form-group Form-controls"
    }, m(Button, {
      className: "Button Button--primary Button--block",
      type: "submit",
      loading: this.loading
    }, app.translator.trans('flarum-messages.forum.rename_dialog_modal.submit_button')))));
  }
  onsubmit(e) {
    e.preventDefault();
    const name = this.name().trim();
    if (name === (this.attrs.dialog.name() || '')) {
      this.hide();
      return;
    }
    this.loading = true;
    return this.attrs.dialog.save({
      name: name || null
    }).then(() => {
      this.attrs.onsave?.();
      this.hide();
    }, () => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('flarum-messages', 'forum/components/RenameDialogModal', RenameDialogModal);